exploreUrl:
@js:// jmtt exploreUrl v2.1 - 四类型切换 + 分类/榜单直入口 + 原站筛选（exploreUrl @js 返回 JSON 字符串）
// 说明：类型仍用 select 切换；分类和榜单不用下拉，直接生成可点 URL 入口。
//       列表 URL 由 {{jmHost(source)}} 在请求时解析当前线路，{{page>1?...}} 在请求时拼页码，
//       因此切换线路后旧发现项也能自动跟随，无需清缓存。
(function () {
  var TYPES = ['漫画', '小说', '视频', '短剧'];
  var T = jmInfo(infoMap, '类型', '小说');
  if (TYPES.indexOf(T) < 0) T = '小说';

  var rows = [];
  var HOST = '{{jmHost(source)}}';
  var PG_ALL = "{{page>1?('/page/'+page):''}}";
  var PG_ONE = "{{page>1?('/'+page):''}}";

  var CATS = {
    '漫画': [['全部', '/comic/all'], ['爱情', '/comic/all/aq'], ['BL', '/comic/all/bl'], ['单本', '/comic/all/db'], ['短篇', '/comic/all/dp'], ['韩漫', '/comic/all/hg'], ['剧情', '/comic/all/jq'], ['乱伦', '/comic/all/ll'], ['奇幻', '/comic/all/qh'], ['日漫', '/comic/all/rb'], ['调教', '/comic/all/tj'], ['同人', '/comic/all/tr'], ['校园', '/comic/all/xy']],
    '小说': [['全部', '/novel/all'], ['原创', '/novel/original'], ['都市激情', '/novel/all/dsjq'], ['校园春色', '/novel/all/xycs'], ['乡村爱情', '/novel/all/xcaq'], ['系统异能', '/novel/all/xtyn'], ['家庭乱伦', '/novel/all/jtll'], ['穿越重生', '/novel/all/cycs'], ['经典武侠', '/novel/all/jdwx'], ['同人改编', '/novel/all/trgb'], ['科学幻想', '/novel/all/kxhx'], ['东方玄幻', '/novel/all/dfxh'], ['娱乐明星', '/novel/all/ylmx'], ['历史架空', '/novel/all/lsjk'], ['西方魔幻', '/novel/all/xfmh'], ['贤者小说', '/novel/all/xzxs']],
    '视频': [['全部', '/mv/all'], ['AI短剧', '/mv/all/aidj'], ['国产视频', '/mv/all/gcsp'], ['日本AV', '/mv/all/rbav'], ['H动漫', '/mv/all/hdm'], ['偷拍摄像', '/mv/all/tp'], ['次元萝莉', '/mv/all/cyll'], ['国产传媒', '/mv/all/gccm'], ['主播福利', '/mv/all/zbfl'], ['吃瓜爆料', '/mv/all/cgbl'], ['无码流出', '/mv/all/wmlc'], ['高清AV', '/mv/all/gqav'], ['同人热播', '/mv/all/trrb'], ['3D动漫', '/mv/all/3ddm']],
    '短剧': [['全部', '/drama/all'], ['AI短剧', '/drama/all/aidduanju']]
  };

  var SEG = { '漫画': 'comic', '小说': 'novel', '视频': 'mv', '短剧': 'drama' };
  var DEF_SORT = { '漫画': '最新更新', '小说': '最新更新', '视频': '最新上架', '短剧': '最新上架' };
  var PERIODS = [['人气日榜', 'day'], ['人气周榜', 'week'], ['人气月榜', 'month'], ['人气年榜', 'year']];

  function pick(arr, v) {
    for (var i = 0; i < arr.length; i++) if (arr[i] === v) return v;
    return arr[0];
  }

  function info(k, d) { return jmInfo(infoMap, k, d); }

  function addSel(title, chars, def, style) {
    rows.push({ title: title, type: 'select', chars: chars, default: pick(chars, def), action: 'java.refreshExplore()', style: style || {} });
  }

  function addTog(title, chars, def, style) {
    rows.push({ title: title, type: 'toggle', chars: chars, default: pick(chars, def), action: 'java.refreshExplore()', style: style || {} });
  }

  function qsOf(t, sort) {
    var q = [];
    if (t === '小说' || t === '漫画') {
      var st = info(t + '状态', '全部');
      if (st === '连载中') q.push('status=' + (t === '小说' ? '2' : '1'));
      else if (st === '已完结') q.push('status=' + (t === '小说' ? '1' : '2'));
    }
    if (t === '小说') {
      var ln = info('小说字数', '全部');
      var lv = { '10万以下': '1', '10—50万': '2', '50—100万': '3', '100万以上': '4' }[ln] || '';
      if (lv) q.push('length=' + lv);
    }
    if (t === '视频') {
      var sb = info('视频字幕', '全部');
      if (sb === '中文字幕') q.push('subtitle=zh');
      else if (sb === '无字幕') q.push('subtitle=none');
    }
    if (t === '视频' || t === '短剧') {
      var du = info(t + '时长', '全部');
      var dv = { '30分钟以下': '1', '30—60分钟': '2', '60分钟以上': '3' }[du] || '';
      if (dv) q.push('duration=' + dv);
    }
    if (t === '短剧' && sort === '最多收藏') q.push('sort=collect');
    return q.join('&');
  }

  // 非默认排序（hot/freshest/last_published/collect）站点会丢分类，只给一个总入口
  function sortBase(t, sort) {
    if (t === '小说') {
      if (sort === '最多观看') return '/novel/hot';
      if (sort === '最新上架') return '/novel/last_published';
    } else if (t === '漫画') {
      if (sort === '最多观看') return '/comic/hot';
      if (sort === '最新上架') return '/comic/freshest';
    } else if (t === '视频') {
      if (sort === '最多播放') return '/mv/hot';
      if (sort === '最多收藏') return '/mv/collect';
    } else {
      if (sort === '最多播放') return '/drama/hot';
      if (sort === '最多收藏') return '/drama/all';
    }
    return '';
  }

  function listUrl(base, qs) {
    var pg = /^\/(comic|novel|mv|drama)\/all$/.test(base) ? PG_ALL : PG_ONE;
    return HOST + base + pg + (qs ? '?' + qs : '');
  }

  function filterLabel(t) {
    var a = [];
    var st = info(t + '状态', '全部'); if (st && st !== '全部') a.push(st);
    if (t === '小说') { var ln = info('小说字数', '全部'); if (ln && ln !== '全部') a.push(ln); }
    if (t === '视频') { var sb = info('视频字幕', '全部'); if (sb && sb !== '全部') a.push(sb); }
    if (t === '视频' || t === '短剧') { var du = info(t + '时长', '全部'); if (du && du !== '全部') a.push(du); }
    return a.length ? ('（' + a.join('·') + '）') : '';
  }

  function addCategoryEntries() {
    var sort = info(T + '排序', DEF_SORT[T]);
    var qs = qsOf(T, sort);
    var fl = filterLabel(T);
    var special = sortBase(T, sort);
    if (special) {
      rows.push({ title: '📚 ' + T + '·全部' + fl + '（' + sort + '，站点此排序不带分类）', type: 'url', url: listUrl(special, qs), style: { layout_wrapBefore: true } });
      return;
    }
    var cats = CATS[T];
    for (var i = 0; i < cats.length; i++) {
      var name = cats[i][0], base = cats[i][1];
      // 原创页 base 是 /novel/original，仍需用 /N 分页
      rows.push({ title: (i === 0 ? '📚 ' : '📖 ') + T + '·' + name + fl, type: 'url', url: listUrl(base, qs), style: i === 0 ? { layout_wrapBefore: true } : {} });
    }
  }

  function addRankEntries() {
    var seg = SEG[T];
    for (var i = 0; i < PERIODS.length; i++) {
      var label = PERIODS[i][0], period = PERIODS[i][1];
      var u = "{{page>1?(jmHost(source)+'/search/__jmrank_end__'):(jmHost(source)+'/" + seg + "/rank?period=" + period + "')}}";
      rows.push({ title: '🏆 ' + T + '·' + label, type: 'url', url: u, style: i === 0 ? { layout_wrapBefore: true } : {} });
    }
  }

  // ===== 顶部：类型 =====
  addSel('类型', TYPES, T, { layout_wrapBefore: true });

  // ===== 原站筛选（分类和榜单已改为直入口，不再下拉） =====
  if (T === '小说') {
    addSel('小说状态', ['全部', '连载中', '已完结'], info('小说状态', '全部'), {});
    addSel('小说字数', ['全部', '10万以下', '10—50万', '50—100万', '100万以上'], info('小说字数', '全部'), {});
    addSel('小说排序', ['最新更新', '最多观看', '最新上架'], info('小说排序', '最新更新'), { layout_wrapBefore: true });
  } else if (T === '漫画') {
    addSel('漫画状态', ['全部', '连载中', '已完结'], info('漫画状态', '全部'), {});
    addSel('漫画排序', ['最新更新', '最多观看', '最新上架'], info('漫画排序', '最新更新'), { layout_wrapBefore: true });
  } else if (T === '视频') {
    addSel('视频字幕', ['全部', '中文字幕', '无字幕'], info('视频字幕', '全部'), {});
    addSel('视频时长', ['全部', '30分钟以下', '30—60分钟', '60分钟以上'], info('视频时长', '全部'), {});
    addSel('视频排序', ['最新上架', '最多播放', '最多收藏'], info('视频排序', '最新上架'), { layout_wrapBefore: true });
  } else {
    addSel('短剧时长', ['全部', '30分钟以下', '30—60分钟', '60分钟以上'], info('短剧时长', '全部'), {});
    addSel('短剧排序', ['最新上架', '最多播放', '最多收藏'], info('短剧排序', '最新上架'), { layout_wrapBefore: true });
  }

  // ===== 分类 / 榜单：直接入口 =====
  addCategoryEntries();
  addRankEntries();

  return JSON.stringify(rows);
})()

jsLib:
// jmLib v2.0 - 禁漫天堂(tekovaki) 公共工具
// jsLib 作用域没有 java/source，所有依赖它们的函数必须显式传参
var JM_UA = 'Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.6367.82 Mobile Safari/537.36';
var JM_HOST_DEF = 'https://abandon.tekovaki.cc';
var JM_PUB_DEF = 'https://jmtt2.net';

function jmStr(v) {
  var s = String(v == null ? '' : v);
  if (s === 'null' || s === 'undefined') s = '';
  return s;
}

function jmUA() { return JM_UA; }

function jmHost(sv) {
  try {
    var h = jmStr(sv.get('jmV2Host'));
    if (h.indexOf('http') === 0) return h.replace(/\/+$/, '');
  } catch (e) {}
  return JM_HOST_DEF;
}

function jmAbs(sv, p) {
  var s = jmStr(p);
  if (s === '') return '';
  if (s.indexOf('http') === 0) return s;
  return jmHost(sv) + (s.charAt(0) === '/' ? '' : '/') + s;
}

function jmOpt(t) {
  return ',{"headers":{"User-Agent":"' + JM_UA + '"},"timeout":' + (t || 20000) + '}';
}

function jmImgProxyOn(sv) {
  try { if (jmStr(sv.get('jmV2ImgProxy')) === '0') return false; } catch (e) {}
  return true;
}

function jmImg(jv, sv, u) {
  var s = jmStr(u);
  if (s === '') return '';
  if (!jmImgProxyOn(sv)) return s;
  var p = s.replace(/^https?:\/\/[^\/]+/, '');
  p = p.split('?')[0].split('#')[0];
  if (p === '' || p.charAt(0) !== '/') return s;
  var ext = p.split('.').pop().toLowerCase();
  if (!/^(jpg|jpeg|png|gif|webp|bmp)$/.test(ext)) ext = 'jpg';
  var b = '';
  try { b = jmStr(jv.base64Encode(p)).replace(/=+$/, ''); } catch (e2) { return s; }
  return jmHost(sv) + '/social-cover/' + b + '.' + ext;
}

function jmTxt(h) {
  var s = String(h == null ? '' : h);
  s = s.replace(/<br\s*\/?>/gi, '\n');
  s = s.replace(/<\/p\s*>/gi, '\n');
  s = s.replace(/<[^>]+>/g, '');
  s = s.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
  s = s.replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&apos;/g, "'");
  s = s.replace(/&#(\d+);/g, function (_, n) { return String.fromCharCode(parseInt(n, 10)); });
  s = s.replace(/\r/g, '');
  s = s.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n');
  return s.replace(/^\s+|\s+$/g, '');
}

function jmFirst(s, re) {
  var m = String(s == null ? '' : s).match(re);
  return m ? m[1] : '';
}

function jmInfo(m, k, d) {
  var v = '';
  try { v = m[k]; } catch (e) {}
  v = jmStr(v);
  if (v === '') { try { v = jmStr(m.get(k)); } catch (e2) {} }
  if (v === '') v = d;
  return v;
}

