// jmtt loginUrl v2.0 - 线路获取/测速/切换 + 图片代理开关（V1 静态 loginUi 的 action 函数库）
// 本作用域独立于 jsLib；action 里没有 source，统一用传入的 java(=SourceLoginJsExtensions) 读写变量。
var JM_UA = 'Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.6367.82 Mobile Safari/537.36';
var JM_HOST_DEF = 'https://abandon.tekovaki.cc';
var JM_PUB_DEF = 'https://jmtt2.net';

function login() {
  return '游客可直接阅读，无需登录。线路与图片代理请用下方按钮管理。';
}

function jmStr(v) {
  var s = String(v == null ? '' : v);
  if (s === 'null' || s === 'undefined') s = '';
  return s;
}

function jmToast(jv, msg, isLong) {
  try { if (isLong) { jv.longToast(msg); } else { jv.toast(msg); } } catch (e) {}
}

function jmMapGet(m, k) {
  var v = '';
  try { v = jmStr(m[k]); } catch (e) {}
  if (v === '') { try { v = jmStr(m.get(k)); } catch (e2) {} }
  return v;
}

// result 是当前面板输入值 Map（action 里由 App 注入）；jv.get 是已保存的源变量
function jmPubVal(jv, res) {
  var v = jmMapGet(res, 'jmPub');
  if (v.indexOf('http') !== 0) { try { v = jmStr(jv.get('jmV2Pub')); } catch (e) {} }
  if (v.indexOf('http') !== 0) v = JM_PUB_DEF;
  return v.replace(/\/+$/, '');
}

function jmSavePub(jv, res) {
  var v = jmPubVal(jv, res);
  try { jv.put('jmV2Pub', v); } catch (e) {}
  jmToast(jv, '✅ 发布页已保存：' + v);
  try { jv.reLoginView(false); } catch (e2) {}
}

function jmIsErr(r) {
  var s = String(r == null ? '' : r);
  if (s === '') return true;
  if (s.indexOf('Exception') >= 0) return true;
  if (s.indexOf('java.') === 0) return true;
  if (s.indexOf('Caused by') >= 0) return true;
  return false;
}

function jmPing(jv, u) {
  var t0 = Date.now();
  var r = '';
  try {
    r = String(jv.ajax(u + '/favicon.ico,{"timeout":8000}'));
  } catch (e) {
    return { ok: false, ms: -1 };
  }
  var ms = Date.now() - t0;
  if (jmIsErr(r) || r.length < 2000) return { ok: false, ms: ms };
  return { ok: true, ms: ms };
}

function jmSpeedTest(jv, cands, autoSwitch) {
  var best = -1;
  var bestMs = 9999999;
  var msg = '';
  for (var i = 0; i < cands.length; i++) {
    var u = cands[i];
    var p = jmPing(jv, u);
    try { jv.put('jmV2Line' + i, u); } catch (e1) {}
    try { jv.put('jmV2Lat' + i, p.ok ? (p.ms + 'ms') : '超时'); } catch (e2) {}
    if (p.ok && p.ms < bestMs) { bestMs = p.ms; best = i; }
    msg += (i + 1) + '. ' + String(u).replace('https://', '') + ' → ' + (p.ok ? (p.ms + 'ms') : '超时') + '\n';
  }
  if (best >= 0) {
    if (autoSwitch) {
      try { jv.put('jmV2Host', cands[best]); } catch (e3) {}
      msg += '✅ 已自动切换到最快线路：' + String(cands[best]).replace('https://', '') + '（' + bestMs + 'ms）';
    } else {
      msg += '✅ 测速完成，最快：' + String(cands[best]).replace('https://', '') + '（' + bestMs + 'ms）';
    }
  } else {
    msg += '❌ 全部线路超时/不可用，请更换发布页或稍后再试';
  }
  jmToast(jv, msg, true);
  try { jv.reLoginView(false); } catch (e4) {}
}

function jmFetchLines(jv, res) {
  var pub = jmPubVal(jv, res);
  jmToast(jv, '⏳ 正在从发布页获取线路：' + pub, true);
  var html = '';
  try {
    html = String(jv.ajax(pub + ',{"timeout":15000}'));
  } catch (e) {
    jmToast(jv, '❌ 发布页请求异常：' + String(e).substring(0, 80), true);
    return;
  }
  if (jmIsErr(html)) {
    jmToast(jv, '❌ 发布页打不开（可能被墙），请改用 jmtt2.net / 18mh.co', true);
    return;
  }
  var mw = html.match(/words\s*=\s*'([a-z,]+)'/);
  if (!mw) {
    jmToast(jv, '❌ 发布页里没有找到线路词表，请检查发布页地址', true);
    return;
  }
  var md = html.match(/words\.random\(\)\s*\+\s*'\.([a-z0-9.\-]+)'/);
  var sfx = md ? md[1] : 'tekovaki.cc';
  var words = mw[1].split(',');
  var cands = ['https://abandon.' + sfx];
  var tries = 0;
  while (cands.length < 6 && tries < 200) {
    tries++;
    var w = words[Math.floor(Math.random() * words.length)];
    var u = 'https://' + w + '.' + sfx;
    if (cands.indexOf(u) < 0) cands.push(u);
  }
  jmToast(jv, '✅ 词表 ' + words.length + ' 个词，域名 ' + sfx + '，开始测速 ' + cands.length + ' 条线路…', true);
  jmSpeedTest(jv, cands, true);
}

function jmTestAll(jv) {
  var cands = [];
  for (var i = 0; i < 6; i++) {
    var u = '';
    try { u = jmStr(jv.get('jmV2Line' + i)); } catch (e) {}
    if (u.indexOf('http') === 0 && cands.indexOf(u) < 0) cands.push(u);
  }
  if (cands.length === 0) {
    jmToast(jv, '⚠️ 还没有线路，请先点「📡 一键从发布页获取线路」');
    return;
  }
  jmToast(jv, '⏳ 开始测试 ' + cands.length + ' 条线路延时…', true);
  jmSpeedTest(jv, cands, false);
}

function jmPickLine(jv, idx) {
  var u = '';
  try { u = jmStr(jv.get('jmV2Line' + idx)); } catch (e) {}
  if (u.indexOf('http') !== 0) {
    jmToast(jv, '⚠️ 线路' + (idx + 1) + '为空，请先获取线路');
    return;
  }
  jmToast(jv, '⏳ 正在测试线路' + (idx + 1) + '：' + u.replace('https://', ''), true);
  var p = jmPing(jv, u);
  if (p.ok) {
